    } else
      cancelled = Object.freeze({
        policy: DEMON_HUNTER_POLICY,
        actorId: n.binding.actorId,
        day: n.day,
        targetId: choice.targetId,
        reason: "authority_revoked",
        faultId,
      });
  }
  n.frozen = true;
