import type { Locale } from "@ai-werewolf-arena/game-contract";

/**
 * bootstrap 负责把“配置”装配成“可运行对局上下文”。
 * 这是服务层启动游戏引擎的唯一入口。
 */
export interface BootstrapResult {
  world: World;
  readonly boardConfig: ReadonlyBoardConfig;
  readonly parameters: BoardParameters;
  readonly rulePlan: RulePlan;
  phaseManager: PhaseManager;
  playerIds: EntityId[];
  random: RandomSource;
  dealMode: "random" | "fixed";
}

export interface BootstrapOptions {
  locale?: Locale;
  playerNames?: Readonly<Record<string, string>>;
  random?: RandomSource;
  /** 仅供 controller fixture：明确牌堆仍按原数量严格验证。 */
  fixedRoles?: readonly Role[];
  /** 显式离线因果测试输入，不是板子或模型参数。 */
  faultPlan?: unknown;
}

/**
 * 按板子配置完成一次完整引擎装配，返回可直接运行的上下文对象。
 */
export function bootstrapGame(
  config: BoardConfig,
  options: BootstrapOptions = {},
): BootstrapResult {
  const world = new World(options.locale);
  const random = options.random ?? createRandom();
  // 先完成实体与组件初始化，再创建系统与管理器，避免空引用。
  const initialized = createPlayers(world, config, options, random);
  const playerIds = initialized.playerIds;
  const parameters = initialized.parameters;
  const boardConfig = parameters.board;
  assignInitialSheriff(world, boardConfig, playerIds);

  const roleRegistry = createDefaultRoleRegistry();
  const damageResolutionSystem = new DamageResolutionSystem();
  const conditionRegistry = new ConditionRegistry(
    boardConfig.pureWhite || boardConfig.animalDream
      ? new PureWhiteWinRegistry(
          createEliminationWinConditionSpecs(
            boardConfig.pureWhite?.eliminationPriority ?? "awa_wolf_priority_v1",
          ),
        )
      : getDefaultWinConditionRegistry(),
  );
  const toolGateway = new ToolGateway();

  const phaseManager = new PhaseManager(
    world,
    boardConfig,
    toolGateway,
    roleRegistry,
    conditionRegistry,
    damageResolutionSystem,
    random,
    { faultPlan: options.faultPlan },
  );

  return Object.freeze({
    world,
    boardConfig,
    parameters,
    rulePlan: phaseManager.getRulePlan(),
    phaseManager,
    playerIds,
    random,
    dealMode: options.fixedRoles ? "fixed" : "random",
  });
}

function createPlayers(
  world: World,
  inputConfig: BoardConfig,
  options: BootstrapOptions,
  random: RandomSource,
): { playerIds: EntityId[]; parameters: BoardParameters } {
  const fixedRoles = options.fixedRoles;
  const dealRandom = random.fork("deal");
  const candidateParameters = BoardParameters.compile(inputConfig);
  const config = candidateParameters.board;
  const roles = buildRoleDeck(config, fixedRoles, dealRandom);
  const parameters = bindBoardParameters(world, candidateParameters);
  const ids: EntityId[] = [];
  const roleCatalog = getDefaultRoleCatalog();

  for (let seat = 1; seat <= config.boardSize; seat++) {
    const entityId = world.createEntity();
    const role = roles[seat - 1];
    // 初始 Camp 是唯一待安装对象；init 可改它，运行 source 则只查询实际 World，不回退 draft。
    const initialCamp = createCampComponent(roleCatalog.getCamp(role), world.locale);
    const roleComp = createRoleComponent(role, world.locale);
    const currentCamp = () => world.getComponent(entityId, COMPONENT.Camp);
    roleCatalog.applyRuntime(roleComp, { boardConfig: config, locale: world.locale, world, initialCamp, currentCamp });

    world.addComponent(
      entityId,
      COMPONENT.Identity,
      createIdentityComponent(
        entityId,
        seat,
        options.playerNames?.[String(seat)] ??
          text(world.locale, "common.player_name", { id: seat }),
      ),
    );
    world.addComponent(entityId, COMPONENT.Role, roleComp);
    world.addComponent(entityId, COMPONENT.Camp, initialCamp);
    const membership = roleCatalog.requireRuntime(role).initialVictoryAffiliations;
    world.addComponent(
      entityId,
      COMPONENT.Victory,
      createVictoryComponent(
        typeof membership === "function"
          ? membership(roleComp, { boardConfig: config, locale: world.locale, initialCamp, currentCamp })
          : (membership ?? [{ kind: "faction", faction: (() => {
              // 仅默认分支在原字段点晚查；自定义 membership 仍持独立无 World 的上下文。
              const camp = currentCamp();
              if (!camp) throw new Error("role_current_camp_missing");
              return camp.camp;
            })() }]),
      ),
    );
    world.addComponent(entityId, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(entityId, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      entityId,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(entityId, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    ids.push(entityId);
  }

  if (config.roleSetups.some((row) => row.role === Role.Thief && row.count === 1))
    installThiefDeal(world, roles, ids);
  if (config.roleSetups.some((row) => row.role === Role.Shapeshifter && row.count === 1))
    installShapeshifterDeal(world, roles, ids);
  installInitialRoster(world);
  if (config.animalDream) installAnimalAuthority(world, config);
  if (roles.includes(Role.Alchemist) || roles.includes(Role.RavenClawWolf))
    installMistRavenBoard(world);
  if (config.radiantEclipse) installRadiantEclipseBoard(world);
  if (roles.includes(Role.DayScholar) || roles.includes(Role.NightMentor))
    installScholarMentorBoard(world);
  if (roles.includes(Role.TimeWolfConsort)) installTimeConsortBoard(world);
  if (roles.includes(Role.Trickster)) installTricksterBoard(world);
  if (roles.includes(Role.Magician)) installMagicianBoard(world);
  if (roles.includes(Role.WolfSorcerer)) installWolfSorcererBoard(world);
  if (roles.includes(Role.OrderPrince)) installOrderPrinceBoard(world);
  if (roles.includes(Role.EvilKnight)) installEvilKnightBoard(world);
  if (roles.includes(Role.NightmareShadow)) installNightmareBoard(world);
  if (config.nobleSecretBody)
    installNobleBodyAuthority(
      world,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.NightNoble)!,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.AwakenedIdiot)!,
    );
  if (roles.includes(Role.DemonHunter)) installDemonHunter(world, config);
  if (roles.includes(Role.GhostBride)) installGhostBride(world, config);
  installWildChild(world, config);
  installLonelyGirl(world, config);
  return { playerIds: ids, parameters };
}

function buildRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  random: RandomSource,
): Role[] {
  const deck = buildSupportedRoleDeck(config, fixedRoles, getDefaultRoleCatalog, supportsWallRoles);
  return fixedRoles ? deck : shuffled(deck, random);
}

/**
 * 负责从原 World 与明确阶段构造引擎行动请求。输入为演员、窗口、允许工具和中立摘要；
 * 输出固定日次、阶段、约束及玩家可见事实，完整构造之后交规则集按原顺序接线机制绑定。
 * 具体机制仍唯一持有权限、期限别名与资源提交；本工厂不计算或写 deadlineAtMs，请求数据副本不是行动许可。
 * 本工厂不渲染本地化文案、不序列化运行范围，也不据阶段字符串新增角色权限。
 */
import { bindRulesetActionRequest } from "../../rulesets/action-request-bindings";
import type { ActionRequestConstructionInput, ActionRequestConstructionPort } from "../../core/domain/actions";
import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import { World } from "../../core/domain/world";
import { buildAgentVisibleEventFeed } from "./agent_visible_event_feed";
import { buildTurnConstraintContext } from "./turn_constraints_context";

/**
 * 统一创建游戏对 Agent 的行动请求。
 *
 * 该工厂统一填入原生请求的日次、细粒度 stage、玩家可见事件与结构化行动约束；
 * 调用方提供机制附加数据，运行时权限仍由具体机制保存，不混入这些公共字段。
 * 事件输出按 actorId 投影；日次取构造输入，不从 World 当前时钟重新推断。
 * 完整数据先构造再绑定原请求对象，clone／约束／投影失败时不进入规则集绑定。
 */
export class GameActionRequestFactory implements ActionRequestConstructionPort {
  constructor(
    // 保留原 World／事件数组引用；readonly 仅限制这里的类型写法，不拍摄快照或冻结输入。
    private readonly world: World,
    private readonly events: readonly GameEvent[],
    private readonly day: number,
  ) {}

  create(input: ActionRequestConstructionInput): ActionRequest {
    // 先按原顺序复制 allowedTools，再克隆机制附加 context；运行句柄不可借公共数据副本成为凭据。
    // 后面的公共字段覆盖附加数据中同名字段；不提前缓存 input getter 或吞掉 clone 的原错误。
    const request: ActionRequest = {
      phase: input.phase,
      actorId: input.actorId,
      allowedTools: [...input.allowedTools],
      ...(input.actionWindow ? { actionWindow: input.actionWindow } : {}),
      context: {
        ...structuredClone(input.context ?? {}),
        day: this.day,
        stage: input.stage,
        turn_constraints: buildTurnConstraintContext({
          requiresAction: input.requiresAction,
          allowedTools: input.allowedTools,
          summary: input.summary,
        }),
        // 等约束构造完成才复制当前事件数组并生成该演员视图，不将整份内部事件数组直接当成玩家事实。
        visible_events: buildAgentVisibleEventFeed(this.world, [...this.events], input.actorId),
      },
    };
    // 完整请求原对象交给各机制建立运行关联；ID／context／期限字段本身不能替代原对象绑定。
    // 原输入的阶段仍逐分支读取，不用已构造的 context.stage 替代后续 getter；World 也只在命中时读。
    // 绑定中抛错仍原样传播，已经建立的前面关联不由本工厂回滚。
    bindRulesetActionRequest(request, {
      stage: () => input.stage,
      world: () => this.world,
    });
    return request;
  }
}

/**
 * 负责有限角色及墙事件的请求绑定组合。输入为工厂已构造的原请求和延迟阶段／World 查询；
 * 输出是在原机制所有者中建立的请求关联，顺序为孤独少女、野孩子、初始身份、墙、鬼新娘。
 * 各分支独立判断，保留初始身份的短路和阶段重复读取；命中时才读取 World，失败不撤销前面的绑定。
 * 权限及期限别名仍归具体机制的原 WeakMap 和守卫；本组合不复制请求、创建库存或授予新许可。
 */
import type { ActionStage } from "@ai-werewolf-arena/game-contract";
import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
import type { World } from "../core/domain/world";
import { bindGhostBrideRequest } from "../game/mechanisms/roles/ghost_bride/authority";
import { bindLonelyGirlRequest } from "../game/mechanisms/roles/lonely_girl/lifecycle";
import { bindWildChildRequest } from "../game/mechanisms/roles/wild_child/lifecycle";
import { bindInitialIdentityRequest } from "../game/mechanisms/roles/initial_identity/setup";
import { bindWallRequest } from "../game/mechanisms/events/wall_notes/authority";

/** 查询保原表达式位置；工厂使用自己的输入与 World，阶段不能从请求快照反推。 */
export interface ActionRequestBindingQueries {
  stage(): ActionStage;
  world(): World;
}

/** 只组合已有绑定命令；请求、context 与具体机制状态保持原引用，异常继续沿原调用路径抛出。 */
export function bindRulesetActionRequest(
  request: ActionRequest,
  queries: ActionRequestBindingQueries,
): void {
  if (queries.stage() === "lonely_girl") bindLonelyGirlRequest(queries.world(), request);
  if (queries.stage() === "wild_child") bindWildChildRequest(queries.world(), request);
  if (queries.stage() === "thief" || queries.stage() === "shapeshifter")
    bindInitialIdentityRequest(queries.world(), request);
  // 墙分支原本就在初始身份与鬼新娘之间；不能为按角色分组而改变绑定及失败前缀。
  if (queries.stage() === "wall_notes") bindWallRequest(queries.world(), request);
  if (
    [
      "ghost_bride_groom",
      "ghost_bride_chat",
      "ghost_bride_witness",
      "ghost_bride_knife",
      "wolf_vote",
    ].includes(queries.stage())
  )
    bindGhostBrideRequest(queries.world(), request);
}

/**
 * 负责请求对象上的交付检查、完成回调和期限别名传播。输入为机制已经绑定的原请求、
 * 当前性查询及不透明完成身份；输出为同步交付检查、一次性结算通知和有序别名绑定。
 * 元数据仅存运行时弱表，不进入模型上下文或归档。机制仍拥有权限、最早期限及单调撤权；
 * 本模块只调用已注册的规则，不以缺少交付检查或相同 JSON 字段判定请求已获授权。
 * 本模块仅写入交付弱表，不修改生命、库存或阶段；结算先删除待通知项再调用回调，异常不恢复。
 * 别名传播遇异常即停止，已完成的绑定不回滚。
 */
import type { ActionRequest } from "./actions";

type AliasPropagation = (original: ActionRequest, alias: ActionRequest) => void;
/** 原请求与别名各自登记元数据；completion 可指向同一机制窗口，不是可序列化许可。 */
interface DeliveryMetadata {
  /** 查询是否可交付；具体原体、生命版本与永久撤权由机制的查询实现负责。 */
  current?: () => boolean;
  /** 将一次 Provider 返回关联到后续领域提交或关闭，不把返回动作当成提交成功。 */
  completion?: object;
  /** 回调身份是键；同一回调重登记只更新顺序，具体别名绑定仍由该机制执行。 */
  aliases?: Map<AliasPropagation, number>;
}

/** 弱表按对象身份关联：复制请求字段不会复制当前性检查或完成身份。 */
const guards = new WeakMap<object, DeliveryMetadata>();
/** 同一完成身份同时最多保留一个待结算回调；原请求和合法别名可共享该身份。 */
const settlements = new WeakMap<object, (accepted: boolean) => void>();
/** 机制成功绑定后登记一次交付检查；保留此前已登记的别名路由。 */
export function bindRequestDeliveryGuard(
  request: object,
  isCurrent: () => boolean,
  completion?: object,
): void {
  const existing = guards.get(request);
  if (existing && "current" in existing)
    throw new Error("action_request_delivery_guard_already_bound");
  guards.set(request, { ...existing, current: isCurrent, completion });
}
/** 无登记时不额外拒绝；有检查时必须严格返回 true，不能用真值替代机制确认。 */
export function assertRequestDelivery(request: ActionRequest): void {
  const guard = guards.get(request);
  if (guard && "current" in guard && guard.current!() !== true)
    throw new Error("action_request_delivery_authority_revoked");
}
/** 登记事务请求的延后通知；无完成身份则返回 false，由调用方执行原有即时通知政策。 */
export function deferRequestDelivery(
  request: ActionRequest,
  settle: (accepted: boolean) => void,
): boolean {
  const completion = guards.get(request)?.completion;
  if (!completion) return false;
  if (settlements.has(completion)) throw new Error("action_request_delivery_already_pending");
  settlements.set(completion, settle);
  return true;
}
export function settleRequestDelivery(completion: object, accepted: boolean): void {
  const settle = settlements.get(completion);
  if (!settle) return;
  // 先消费再通知：重入或回调抛错都不会再次发送同一成功／拒绝通知，也不回滚领域前缀。
  settlements.delete(completion);
  settle(accepted);
}

/** 仅登记已成功绑定的路由；登记自身不会执行回调、校验权限或设置期限。 */
export function registerRequestAliasPropagation(
  request: object,
  order: number,
  inherit: AliasPropagation,
): void {
  let metadata = guards.get(request);
  if (!metadata) {
    metadata = {};
    guards.set(request, metadata);
  }
  (metadata.aliases ??= new Map()).set(inherit, order);
}

/** 机制自行接纳并绑定别名；按顺序调用不等于授予新行动权限。 */
export function inheritRequestAlias(original: ActionRequest, alias: ActionRequest): void {
  const routes = guards.get(original)?.aliases;
  if (!routes) return;
  // 先取路由快照再稳定排序；回调期间增删路由不改变本次名单，抛错时后续路由不执行。
  for (const [inherit] of [...routes].sort((left, right) => left[1] - right[1]))
    inherit(original, alias);
}

/** 调用方先计算最早期限；这里保留原字段展开顺序，再由已登记机制绑定新对象。 */
export function deriveBoundedRequest(original: ActionRequest, deadlineAtMs: number): ActionRequest {
  const alias = { ...original, deadlineAtMs };
  inheritRequestAlias(original, alias);
  return alias;
}

/**
 * 负责每局具名随机流；输入种子与路径，输出确定性抽样、独立子流和洗牌副本。
 * 子流只依赖原种子与名字路径，不依赖父流已抽取次数；算法标识用于严格复现，不在此改版本。
 * 元数据及路径冻结，流内部计数仍由实例拥有；抽样能力不包含派生其它流的权限。
 */
export const RANDOM_ALGORITHM = "mulberry32-fnv1a-utf16-v1" as const;
export const RANDOM_STREAM_POLICY = "named-path-v1" as const;

/** 原种子字符串、算法标识和有序路径；trim 仅检查非空，不规范化保存的名字。 */
export interface RandomMetadata {
  seed: string;
  algorithm: typeof RANDOM_ALGORITHM;
  streamPolicy: typeof RANDOM_STREAM_POLICY;
  path: readonly string[];
}

/** 完整运行流可查看复现资料和创建子流；next 每次推进该实例自己的状态。 */
export interface RandomSource {
  readonly metadata: RandomMetadata;
  next(): number;
  fork(name: string): RandomSource;
}

/** 决策方仅取得抽样入口，不取得种子、路径或派生其它流的接口。 */
export interface RandomDraws {
  next(): number;
}

/** 冻结包装对象而不复制流；每次调用仍晚读 source.next 并保原方法 receiver。 */
export function randomDraws(source: RandomSource): RandomDraws {
  return Object.freeze({ next: () => source.next() });
}

class SeededRandom implements RandomSource {
  readonly metadata: RandomMetadata;
  private state: number;

  constructor(seed: string, path: readonly string[] = []) {
    if (!seed.trim()) throw new Error("random_seed_empty");
    this.metadata = Object.freeze({
      seed,
      algorithm: RANDOM_ALGORITHM,
      streamPolicy: RANDOM_STREAM_POLICY,
      path: Object.freeze([...path]),
    });
    // 固定 JSON 数组与 UTF-16 码元参与 FNV-1a；改序列化或按码点迭代都会改变复现序列。
    const input = JSON.stringify([seed, ...path]);
    let hash = 0x811c9dc5;
    for (let index = 0; index < input.length; index++)
      hash = Math.imul(hash ^ input.charCodeAt(index), 0x01000193) >>> 0;
    this.state = hash;
  }

  /** Mulberry32 以无符号 32 位状态推进，输出落在 [0, 1)。 */
  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let value = this.state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 0x100000000;
  }

  /** 同种子／路径／名字重复 fork 得到同序列的新实例，不消耗当前流。 */
  fork(name: string): RandomSource {
    if (!name.trim()) throw new Error("random_stream_name_empty");
    return new SeededRandom(this.metadata.seed, [...this.metadata.path, name]);
  }
}

/** 未传 seed 时才创建随机 UUID；有 seed 的调用保持显式确定性。 */
export function createRandom(seed: string = crypto.randomUUID()): RandomSource {
  return new SeededRandom(seed);
}

/** Fisher–Yates 只改新数组；由尾到头每轮抽取一次，不校验调用方自定义 next 的返回范围。 */
export function shuffled<T>(values: readonly T[], random: RandomSource): T[] {
  const result = [...values];
  for (let index = result.length - 1; index > 0; index--) {
    const target = Math.floor(random.next() * (index + 1));
    [result[index], result[target]] = [result[target], result[index]];
  }
  return result;
}

/**
 * 负责行动提交前的发言文字清洗与领域预检；输入原 World、行动者、调用和上下文，输出原校验结果。
 * JSON Schema 由 ActionReception 持有；本入口按原清洗 → validator 顺序，不消费库存或提交动作。
 * 实例保存原校验器引用，两种发言分支产生浅副本，其它调用保原引用；不是快照、冻结或新许可。
 * getter、清洗与校验异常原样传播，不统一吞错、补偿或保证任意输入都能得到结构化拒绝。
 */
import { sanitizeSpeechText } from "../../utils/speech_text";
import { EntityId, ToolCall, ToolValidationResult } from "../../core/domain/model";
import { World } from "../../core/domain/world";
import { ActionValidator, type ValidationContext } from "./action_validator";

/**
 * 网关只形成清洗后的领域校验候选；预检通过不代表付款、请求完成或实际效果已发生。
 */
export class ToolGateway {
  private readonly validator: ActionValidator;

  constructor(validator: ActionValidator = new ActionValidator()) {
    this.validator = validator;
  }

  /** 先完成清洗再读取并调用原 validator；清洗抛错时不进入校验器，不提前读取 World 或上下文字段。 */
  validateAndSanitize<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const sanitizedCall = this.sanitize(toolCall);
    return this.validator.validate(world, actorId, sanitizedCall, context);
  }

  /** 按原 name 分支读取；仅两种发言造新外层／args 对象，不做其它工具的 schema 或权限校验。 */
  private sanitize<T extends ToolCall>(call: T): T {
    if (call.name === "speak") {
      const raw = call.args.text;
      // 仅清除开头的既有保留前缀并 trim；不删内嵌文字，也不把清洗当作身份认证。
      const text = sanitizeSpeechText(raw);
      // 清洗成功后再按原 spread 次序读取调用和 args；仅浅复制，原嵌套引用与 getter 轨迹保持。
      return {
        ...call,
        args: {
          ...call.args,
          text,
        },
      } as T;
    }
    if (call.name === "speak_to_wolves") {
      const raw = call.args.text;
      const text = sanitizeSpeechText(raw);
      return {
        ...call,
        args: {
          ...call.args,
          text,
          // end_chat 在原两个 spread 与 text 之后才读取，保 Boolean truthiness，不做严格布尔校验。
          end_chat: Boolean(call.args.end_chat),
        },
      } as T;
    }
    // 非发言工具不复制、不归一化参数；领域校验仍在上层的原 validator 调用点执行。
    return call;
  }
}

/**
 * 负责按演员生命、角色、可信行动窗口及已注册规则校验工具调用。输入为已清洗调用及校验上下文，输出为原规则结果与配置的校验 trace。
 * 领域预检通过不等于库存付款，本模块不以 schema 接受代替实际资源提交。
 */
import { RuleError, type RuleViolation } from "@ai-werewolf-arena/game-contract";
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { AliveComponent } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  ActionWindow,
  EntityId,
  Phase,
  ToolCall,
  ToolValidationResult,
} from "../../core/domain/model";
import { getDefaultToolValidationRuleRegistry, ToolValidationRuleRegistry } from "../mechanisms";
import { safeRecordLogicOp } from "../../recording/session_recorder";
import { World } from "../../core/domain/world";

/**
 * 动作校验上下文。
 */
export interface ValidationContext {
  /** 有事务归属的 controller 只在实际提交后记录校验。 */
  deferOperation?: boolean;
  day?: number;
  thiefScope?: object;
  shapeshifterScope?: object;
  wildChildScope?: object;
  lonelyGirlScope?: object;
  ghostBrideScope?: object;
  demonHunterScope?: object;
  nobleBodyScope?: object;
  fragrantPairScope?: object;
  animalScope?: object;
  wallScope?: object;
  wallId?: string;
  itemInstanceId?: string;
  debateId?: string;
  abilityId?: string;
  phase: Phase;
  actionWindow?: ActionWindow;
  allowSelfDestruct?: boolean;
  duelWindow?: import("../../core/domain/identity").KnightDuelWindow;
  allowKnightDuel?: boolean;
  deathActionId?: number;
  sheriffCandidates?: readonly EntityId[];
  badgeCandidates?: readonly EntityId[];
  exileCandidates?: readonly EntityId[];
}

/**
 * ActionValidator 是“规则防线”。
 * 所有模型工具调用在落地前都必须通过这里，非法动作统一返回错误并要求重试。
 */
export class ActionValidator {
  constructor(
    private readonly ruleRegistry: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
    private readonly recordOperations = true,
  ) {}

  validate<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const reject = (violation: RuleViolation): ToolValidationResult<T> => {
      if (this.recordOperations && context.deferOperation !== true)
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId,
          phase: context.phase,
          status: "rejected",
          reason: violation.code,
          input: {
            tool: toolCall.name,
            args: (toolCall as any).args ?? {},
            action_window: context.actionWindow,
          },
        });
      return toolFailure(world.locale, violation.code, violation.message);
    };
    const accept = (): ToolValidationResult<T> => {
      if (this.recordOperations && context.deferOperation !== true)
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId,
          phase: context.phase,
          status: "ok",
          input: {
            tool: toolCall.name,
            args: (toolCall as any).args ?? {},
            action_window: context.actionWindow,
          },
        });
      return {
        ok: true,
        sanitizedCall: toolCall,
      };
    };

    const role = world.getComponent(actorId, COMPONENT.Role);
    const alive = world.getComponent(actorId, COMPONENT.Alive);

    if (!role || !alive) {
      return reject({ code: RuleError.ActorMissing });
    }

    const allowDeadAction = world.hasDeathAction(
      actorId,
      toolCall.name,
      context.phase,
      context.day,
      context.deathActionId,
      context.abilityId,
    );
    if (context.deathActionId !== undefined && (alive.alive || !allowDeadAction)) {
      return reject({ code: RuleError.DeathActionUnavailable });
    }
    if (!alive.alive && !allowDeadAction) {
      return reject({ code: RuleError.ActorDead });
    }
    if (toolCall.name === "choose_badge_successor" && (alive.alive || !allowDeadAction))
      return reject({ code: RuleError.DeathActionUnavailable });
    if (toolCall.name === "shoot" && (alive.alive || !allowDeadAction)) {
      return reject({ code: RuleError.ShootUnavailable });
    }

    const error = this.ruleRegistry.validate({
      world,
      actorId,
      role,
      toolCall,
      phase: context.phase,
      day: context.day,
      thiefScope: context.thiefScope,
      shapeshifterScope: context.shapeshifterScope,
      wildChildScope: context.wildChildScope,
      lonelyGirlScope: context.lonelyGirlScope,
      ghostBrideScope: context.ghostBrideScope,
      demonHunterScope: context.demonHunterScope,
      nobleBodyScope: context.nobleBodyScope,
      fragrantPairScope: context.fragrantPairScope,
      animalScope: context.animalScope,
      wallScope: context.wallScope,
      wallId: context.wallId,
      itemInstanceId: context.itemInstanceId,
      debateId: context.debateId,
      abilityId: context.abilityId,
      actionWindow: context.actionWindow,
      allowSelfDestruct: context.allowSelfDestruct,
      duelWindow: context.duelWindow,
      allowKnightDuel: context.allowKnightDuel,
      sheriffCandidates: context.sheriffCandidates,
      exileCandidates: context.exileCandidates,
      badgeCandidates: context.badgeCandidates,
    });
    if (error) {
      return reject(error);
    }

    return accept();
  }
}

/**
 * 负责普通用药工具的完整准入组合：能力／库存、自救、学者／导师削弱、目标映射与受赠目标限制。
 * 输入为原校验上下文和已清洗工具，输出为原首个结构化拒绝或通过；不执行用药或付款。
 * 读取同一实例和当前 settled frame，不因角色标签限定受赠／复制／转移能力，不建立库存快照。
 * 参数、短路及 getter 失败顺序保持；预检通过不替代实际提交时的原体、生命和来源复验。
 */
import { scholarMentorBlocks } from "../game/mechanisms/roles/scholar_mentor/ports";
import { isMagicianBoard, resolveMagicianNightTarget } from "../game/mechanisms/roles/magician/ports";
import { nativePotionsCanCombine } from "../game/mechanisms/roles/witch/ports";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { PotionType, Phase, WitchSelfHealRule, StatusMark } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../core/domain/components/names";
import { type ToolRuleMap, isAliveTarget } from "../game/mechanisms/validation/contracts";
import { activeNightAbility } from "../game/mechanisms/roles/abilities";
import { luckyTargetAllowed } from "../game/mechanisms/roles/night_action_history";

/** 保留原可写规则表；Catalog 仍晚读当前 callback，不把准入冻结为登记时的授权快照。 */
export const WITCH_VALIDATION_RULES: ToolRuleMap = {
  use_potion: ({ world, actorId, role, toolCall, day, abilityId, phase }) => {
    // 原库存选择也适用于受赠／复制／转移药剂；不新增 Witch 角色标签门槛。
    const ability = activeNightAbility(role, "potion", day ?? 1, abilityId);
    const witchState = ability?.state;
    if (!witchState) {
      return { code: RuleError.WitchOnly };
    }
    if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
    if (toolCall.name !== "use_potion") {
      return { code: RuleError.ToolMismatch };
    }
    if (
      ability?.activation === "lucky" &&
      toolCall.args.potion_type === PotionType.None &&
      toolCall.args.target_id !== actorId
    )
      return { code: RuleError.PoisonTarget };
    if (
      ability?.activation === "black_market" &&
      toolCall.args.potion_type === PotionType.None &&
      !isAliveTarget(world, toolCall.args.target_id)
    )
      return { code: RuleError.PoisonTarget };
    if (toolCall.args.potion_type === PotionType.Heal) {
      const canSelfHeal =
        day === undefined
          ? witchState.canSelfHeal
          : witchState.selfHealRule === WitchSelfHealRule.Always ||
            (witchState.selfHealRule === WitchSelfHealRule.FirstNightOnly && day === 1);
      if (!canSelfHeal && toolCall.args.target_id === actorId) {
        return { code: RuleError.SelfHeal };
      }
      if (witchState.heal <= 0 || witchState.healUsedThisNight) {
        return { code: RuleError.HealUnavailable };
      }
      if (witchState.poisonUsedThisNight && !nativePotionsCanCombine(ability!)) {
        return { code: RuleError.TwoPotions };
      }
      const requestedId = toolCall.args.target_id;
      if (!isAliveTarget(world, requestedId)) return { code: RuleError.HealTarget };
      // 自救先检查请求编号；这里才映射有效目标，缺失 day 的原默认是 0 而非库存查询的 1。
      const mapping = isMagicianBoard(world)
        ? resolveMagicianNightTarget(world, day ?? 0, requestedId)
        : null;
      if (mapping && !mapping.isCurrent()) return { code: RuleError.HealTarget };
      const targetId = mapping?.effectiveId ?? requestedId;
      if (
        !isAliveTarget(world, targetId) ||
        !world.getComponent(targetId, COMPONENT.Role) ||
        !world.getComponent(targetId, COMPONENT.StatusMarks)?.has(StatusMark.WolfKillMark)
      ) {
        return { code: RuleError.HealTarget };
      }
      return null;
    }
    if (toolCall.args.potion_type === PotionType.Poison) {
      // 削弱查询先于瓶数／目标；原 frame 错误原样传播，不转成库存不足或补读目标。
      if (scholarMentorBlocks(world, day ?? 1, actorId, "poison"))
        return { code: RuleError.ModifierUnavailable };
      if (witchState.poison <= 0 || witchState.poisonUsedThisNight) {
        return { code: RuleError.PoisonUnavailable };
      }
      if (witchState.healUsedThisNight && !nativePotionsCanCombine(ability!)) {
        return { code: RuleError.TwoPotions };
      }
      if (!isAliveTarget(world, toolCall.args.target_id)) {
        return { code: RuleError.PoisonTarget };
      }
      if (
        !luckyTargetAllowed(world, actorId, ability!, day ?? 1, "poison", toolCall.args.target_id)
      )
        return { code: RuleError.LuckyTargetRepeat };
      return null;
    }
    return null;
  },
};

/**
 * 负责生产装配前的猎魔人有限板子判定。输入为已规范化的纯板子数据，输出为支持布尔值。
 * 先接受赤月、贵族秘身的已列组合，再检查本模块六人／十二人标准牌组；不是任意猎魔人混搭。
 * 按现有字段、牌组、胜利目标与政策检查，不创建角色、支付资源或授予行动权限。
 * 归档验证拥有独立实现，不以本生产判定作为验证 oracle。
 */
import { isNobleSecretBodyPreset } from "./noble-secret-body";
import { isRedMoonPreset } from "./red-moon";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { DEMON_HUNTER_POLICY } from "@ai-werewolf-arena/game-contract";
function exactDemonData(value: unknown, keys: readonly string[]): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}
const decks: Readonly<Record<number, Readonly<Record<string, number>>>> = {
  6: { wolf: 2, villager: 1, seer: 1, witch: 1, ["demon_hunter"]: 1 },
  12: { wolf: 3, villager: 4, seer: 1, witch: 1, hunter: 1, guard: 1, ["demon_hunter"]: 1 },
};
function equals(value: unknown, expected: Record<string, unknown>): boolean {
  return (
    exactDemonData(value, Object.keys(expected)) &&
    Object.entries(expected).every(([key, v]) => value[key] === v)
  );
}
/** 先按已列组合委托，再检查规范化标准牌组；注册角色不扩大组合支持范围。 */
export function isDemonHunterPreset(input: unknown): boolean {
  // 先按原顺序委托两个完整组合，再进入标准牌组检查；不能把已注册角色视作任意组合许可。
  if (isRedMoonPreset(input) || isNobleSecretBodyPreset(input)) return true;
  try {
    const c = copyEventData(input) as Record<string, any>;
    const required = [
      "boardSize",
      "enableSheriff",
      "demonHunter",
      "roleSetups",
      "hooks",
      "selfDestruct",
      "seer",
      "witch",
      "tieBreaker",
      "voting",
      "disclosure",
      "lastWords",
    ];
    const allowed = [...required, "winCondition", "winConditions", "hunter", "guard", "sheriff"];
    if (
      !c ||
      Array.isArray(c) ||
      !required.every((key) => Object.hasOwn(c, key)) ||
      Object.keys(c).some((key) => !allowed.includes(key)) ||
      ![6, 12].includes(c.boardSize)
    )
      return false;
    const deck = decks[c.boardSize]!;
    if (!Array.isArray(c.roleSetups) || c.roleSetups.length !== Object.keys(deck).length)
      return false;
    const counts: Record<string, number> = {};
    for (const entry of c.roleSetups) {
      if (
        !exactDemonData(entry, ["role", "count"]) ||
        typeof entry.role !== "string" ||
        !Object.hasOwn(deck, entry.role) ||
        Object.hasOwn(counts, entry.role) ||
        entry.count !== deck[entry.role]
      )
        return false;
      counts[entry.role] = entry.count as number;
    }
    if (Object.hasOwn(c, "winConditions") && !Array.isArray(c.winConditions)) return false;
    const goals = c.winConditions ?? (c.winCondition ? [c.winCondition] : []);
    if (
      !Array.isArray(goals) ||
      goals.length !== 1 ||
      !["slaughter_city", "slaughter_side"].includes(goals[0]) ||
      (Object.hasOwn(c, "winCondition") && c.winCondition !== goals[0])
    )
      return false;
    if (
      !equals(c.demonHunter, { policy: DEMON_HUNTER_POLICY }) ||
      c.enableSheriff !== (c.boardSize === 12) ||
      !equals(c.seer, {
        targetPolicy: "awa_alive_v1",
        actionPolicy: "awa_required_when_legal_v1",
      }) ||
      !equals(c.witch, {
        canSelfHeal: "disabled",
        knifeVisibility: "awa_with_heal_v1",
        potionPolicy: "awa_one_native_v1",
      }) ||
      !equals(c.voting, { exilePolicy: "awa_direct_v1" }) ||
      !equals(c.disclosure, { deathRevealPolicy: "awa_hidden_v1" }) ||
      !equals(c.lastWords, { policy: "awa_initial_wave_v1" }) ||
      !equals(c.hooks, {
        onDaybreak: false,
        onPreElection: true,
        onPreVote: true,
        onPerSpeechGap: false,
      }) ||
      !exactDemonData(c.selfDestruct, ["enabledWindows"]) ||
      !Array.isArray(c.selfDestruct.enabledWindows) ||
      c.selfDestruct.enabledWindows.length !== 2 ||
      new Set(c.selfDestruct.enabledWindows).size !== 2 ||
      !c.selfDestruct.enabledWindows.every((w: string) =>
        ["on_pre_election", "on_pre_vote"].includes(w),
      )
    )
      return false;
    if (c.boardSize === 12)
      return (
        equals(c.sheriff, {
          electionPolicy: "awa_final_candidates_v1",
          badgePolicy: "awa_next_seat_v1",
          voteWeight: 1.5,
        }) &&
        equals(c.tieBreaker, {
          sheriffVote: "min_seat",
          wolfKillVote: "min_id",
          exileVote: "min_id",
        }) &&
        equals(c.guard, { repeatPolicy: "netease_consecutive_nights_v1" }) &&
        equals(c.hunter, { deathActionPolicy: "awa_knife_or_exile_v1" })
      );
    return (
      !Object.hasOwn(c, "guard") &&
      !Object.hasOwn(c, "hunter") &&
      !Object.hasOwn(c, "sheriff") &&
      equals(c.tieBreaker, { wolfKillVote: "min_id", exileVote: "min_id" })
    );
  } catch {
    return false;
  }
}

/**
 * 负责按原 World 对象绑定唯一不可变板子参数。输入为完整自有数据配置；输出为深只读
 * 执行视图、独立归档 DTO 或明确的数据／修订错误。Node Proxy 检测先于反射；不执行
 * accessor、迭代器或继承字段。只冻结校验后副本，不冻结调用方对象、World 或处理器。
 * 相等完整输入复用原所有者；同一 World 不支持参数替换或重置。绑定不读 World 方法、
 * 时钟或 RNG，也不授予行动权限；安全结构预检保留原板子拒绝优先级，再做完整 schema 校验。
 */
import { types } from "node:util";
import {
  boardConfigSchema,
  type BoardConfig,
  type ReadonlyBoardConfig,
} from "@ai-werewolf-arena/game-contract";
import { boardPresetViolation } from "./board-support";

// 权威按 World 原对象身份保存；工厂实例与私有构造凭据分别防止外部伪造已编译参数。
const owners = new WeakMap<object, BoardParameters>();
const factoryInstances = new WeakSet<object>();
const constructionToken = Symbol("board-parameters-construction");
const dataError = "rule_parameters_not_data";

/** 先验证自有描述符；只有已证明的纯数据才传给 structuredClone，拒绝路径不触发 getter。 */
function assertData(value: unknown, ancestors: Set<object>, depth: number): void {
  if (
    value === undefined ||
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return;
  if (typeof value !== "object" || types.isProxy(value) || depth > 16 || ancestors.has(value))
    throw new Error(dataError);
  // 数组必须是稠密标准数组；普通对象仅接受标准或 null 原型，symbol／accessor 不进入后续克隆。
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value);
  if (array ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null)
    throw new Error(dataError);
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).some((key) => typeof key !== "string"))
    throw new Error(dataError);
  if (array) {
    const length = descriptors.length?.value;
    if (
      !Number.isSafeInteger(length) ||
      length < 0 ||
      Object.keys(descriptors).length !== length + 1 ||
      !Array.from({ length }, (_, index) => Object.hasOwn(descriptors, String(index))).every(
        Boolean,
      )
    )
      throw new Error(dataError);
  }
  // 只记录当前递归祖先：拒绝环，允许不同路径共享同一数据对象；finally 保持分支隔离。
  ancestors.add(value);
  try {
    for (const [key, descriptor] of Object.entries(descriptors)) {
      if (array && key === "length") continue;
      if (!Object.hasOwn(descriptor, "value") || !descriptor.enumerable) throw new Error(dataError);
      assertData(descriptor.value, ancestors, depth + 1);
    }
  } finally {
    ancestors.delete(value);
  }
}

/** 递归冻结已复制并解析的数据；不把外部输入引用变成只读。 */
function freezeData(value: unknown): void {
  if (!value || typeof value !== "object") return;
  for (const descriptor of Object.values(Object.getOwnPropertyDescriptors(value))) {
    freezeData(descriptor.value);
  }
  Object.freeze(value);
}

/** 比较完整数据值而非字段插入顺序；两侧均已校验，不读取可替换上下文别名。 */
function equalData(left: unknown, right: unknown): boolean {
  if (left === null || right === null || typeof left !== "object" || typeof right !== "object")
    return Object.is(left, right);
  if (Array.isArray(left) !== Array.isArray(right)) return false;
  const leftKeys = Object.keys(left).sort(),
    rightKeys = Object.keys(right).sort();
  return (
    leftKeys.length === rightKeys.length &&
    leftKeys.every(
      (key, index) =>
        key === rightKeys[index] &&
        equalData(
          Object.getOwnPropertyDescriptor(left, key)!.value,
          Object.getOwnPropertyDescriptor(right, key)!.value,
        ),
    )
  );
}

/** 唯一参数所有者持有深冻结配置；encode 返回可修改的独立归档副本，不修改运行规则。 */
export class BoardParameters {
  readonly #board: BoardConfig;

  private constructor(token: typeof constructionToken, board: BoardConfig) {
    if (token !== constructionToken) throw new Error("rule_parameters_constructor_forbidden");
    freezeData(board);
    this.#board = board;
    Object.freeze(this);
    factoryInstances.add(this);
  }

  static compile(input: unknown): BoardParameters {
    assertData(input, new Set(), 0);
    const copied = structuredClone(input);
    // 这里只预检原板子分派会解引用的两份结构；不代表完整规范化通过，也不是运行时许可。
    if (
      !copied ||
      typeof copied !== "object" ||
      Array.isArray(copied) ||
      !Array.isArray(Object.getOwnPropertyDescriptor(copied, "roleSetups")?.value)
    )
      throw new Error("rule_parameters_invalid");
    const rows: unknown[] = Object.getOwnPropertyDescriptor(copied, "roleSetups")!.value;
    const conditions: unknown = Object.getOwnPropertyDescriptor(copied, "winConditions")?.value;
    if (
      (conditions !== undefined && !Array.isArray(conditions)) ||
      rows.some(
        (row) =>
          !row ||
          typeof row !== "object" ||
          Array.isArray(row) ||
          typeof Object.getOwnPropertyDescriptor(row, "role")?.value !== "string" ||
          typeof Object.getOwnPropertyDescriptor(row, "count")?.value !== "number",
      )
    )
      throw new Error("rule_parameters_invalid");
    // 先保留原板子拒绝的错误优先级；后续严格 schema 成功才允许创建参数所有者。
    const violation = boardPresetViolation(copied as ReadonlyBoardConfig);
    if (violation) throw new Error(violation);
    const parsed = boardConfigSchema.safeParse(copied);
    if (!parsed.success) throw new Error("rule_parameters_invalid");
    return new BoardParameters(constructionToken, parsed.data);
  }

  /** 返回所有者的同一只读引用，供运行期按身份核验。 */
  get board(): ReadonlyBoardConfig {
    return this.#board;
  }

  /** 每次产生独立副本；归档数据不能反向替换 World 已绑定的执行参数。 */
  encode(): BoardConfig {
    return structuredClone(this.#board);
  }
}
Object.freeze(BoardParameters.prototype);
Object.freeze(BoardParameters);

function isFactoryParameters(input: object): input is BoardParameters {
  return factoryInstances.has(input);
}

/** 只发布一次；同值新输入仍先校验／编译再复用旧所有者，异值修订按原错误拒绝。 */
export function bindBoardParameters(
  worldIdentity: object,
  input: ReadonlyBoardConfig | BoardParameters,
): BoardParameters {
  const previous = owners.get(worldIdentity);
  // 唯有已绑定视图的同一引用直接返回；其它候选失败不改变旧绑定，首次编译成功后才写入。
  if (previous && input === previous.board) return previous;
  if (types.isProxy(input)) throw new Error(dataError);
  const candidate = isFactoryParameters(input) ? input : BoardParameters.compile(input);
  if (previous) {
    if (!equalData(previous.board, candidate.board))
      throw new Error("rule_parameters_revision_not_supported");
    return previous;
  }
  owners.set(worldIdentity, candidate);
  return candidate;
}

/** 只查原 World 身份的权威绑定；缺失即失败，不信任可替换上下文，也不临时编译新来源。 */
export function requireBoardParameters(worldIdentity: object): BoardParameters {
  const parameters = owners.get(worldIdentity);
  if (!parameters) throw new Error("rule_parameters_not_bound");
  return parameters;
}

/**
 * 负责 bootstrap 的有限板子拒绝顺序与角色牌组构造。输入为原只读板子、可选固定底牌及窄 Catalog／事件支持查询；输出为原可写牌序或首个原拒绝。工厂及资料字段仍在原重复调用点读取，不复制或冻结来源。不创建 World／组件、消费 RNG、解析外部配置或授予权限；洗牌与装配时点仍由 bootstrap 维护。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "@ai-werewolf-arena/game-contract";
import { boardPresetViolation } from "./board-support";

/** 只读元数据查询保留原 Catalog／profile 身份；每次调用仍由装配方取得当前目录。 */
export interface SupportedRoleDeckCatalog {
  readonly requireMetadata: (role: Role) => {
    readonly maxCount?: number;
    readonly supportedWinConditions?: readonly WinCondition[];
    readonly supportedBoardRoles?: readonly Role[];
  };
  readonly getCamp: (role: Role) => Camp;
}

export function buildSupportedRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  getDefaultRoleCatalog: () => SupportedRoleDeckCatalog,
  supportsWallRoles: (roles: readonly Role[]) => boolean,
): Role[] {
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) throw new Error(presetViolation);
  const deck: Role[] = [];
  for (const setup of config.roleSetups) {
    for (let i = 0; i < setup.count; i++) {
      deck.push(setup.role);
    }
  }

  if (
    config.events &&
    (!supportsWallRoles(deck) || config.events.pack !== "awa_wall_notes_once_v1")
  )
    throw new Error("event_pack_combination_not_supported");
  // 先检查事件组合，再按牌组首次出现顺序检查全部角色上限，随后核支持集合；首个失败不继续后续读取。
  const counts = new Map<Role, number>();
  for (const role of deck) counts.set(role, (counts.get(role) ?? 0) + 1);
  for (const [role, count] of counts) {
    const maximum = getDefaultRoleCatalog().requireMetadata(role).maxCount;
    if (maximum !== undefined && count > maximum)
      throw new Error(`role_count_exceeds_limit: ${role}`);
  }
  for (const role of counts.keys()) {
    const profile = getDefaultRoleCatalog().requireMetadata(role);
    const conditions = config.winConditions?.length
      ? config.winConditions
      : [config.winCondition ?? WinCondition.SlaughterCity];
    if (
      profile.supportedWinConditions &&
      (new Set(conditions).size !== conditions.length ||
        conditions.some((condition) => !profile.supportedWinConditions!.includes(condition)))
    )
      throw new Error(`role_win_condition_not_supported: ${role}`);
    const supported = profile.supportedBoardRoles;
    if (supported && [...counts.keys()].some((candidate) => !supported.includes(candidate)))
      throw new Error(`role_combination_not_supported: ${role}`);
  }

  if (deck.length !== config.boardSize) {
    throw new Error(`Role setup mismatch: boardSize=${config.boardSize}, roles=${deck.length}`);
  }

  if (
    config.thief &&
    (!counts.has(Role.Thief) || config.thief.policy !== "lui_meme_thief_two_extra_villagers_v1")
  )
    throw new Error("thief_policy_invalid");
  if (
    config.lonelyGirl &&
    (!counts.has(Role.LonelyGirl) || config.lonelyGirl.policy !== "awa_netease_lonely_girl_v1")
  )
    throw new Error("lonely_girl_policy_invalid");
  if (
    counts.has(Role.LonelyGirl) &&
    (config.boardSize < 6 ||
      !counts.has(Role.Wolf) ||
      ![...counts.keys()].some(
        (role) => role !== Role.LonelyGirl && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
      ))
  )
    throw new Error("lonely_girl_finite_composition_required");
  if (
    config.wildChild &&
    (!counts.has(Role.WildChild) || config.wildChild.policy !== "awa_lui_meme_wild_child_v1")
  )
    throw new Error("wild_child_policy_invalid");
  if (
    counts.has(Role.WildChild) &&
    ((counts.get(Role.Wolf) ?? 0) < 1 ||
      [...counts]
        .filter(
          ([role]) =>
            role !== Role.WildChild && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 1)
  )
    throw new Error("wild_child_finite_composition_required");
  if (
    config.shapeshifter &&
    (!counts.has(Role.Shapeshifter) ||
      config.shapeshifter.policy !== "awa_netease_shapeshifter_two_extra_villagers_v1")
  )
    throw new Error("shapeshifter_policy_invalid");
  if (counts.has(Role.Shapeshifter)) {
    if (
      config.boardSize < 6 ||
      (counts.get(Role.Wolf) ?? 0) < 2 ||
      [...counts]
        .filter(
          ([role]) =>
            role !== Role.Shapeshifter && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 1
    )
      throw new Error("shapeshifter_finite_composition_required");
    deck.push(Role.Villager, Role.Villager);
  }
  if (counts.has(Role.Thief)) {
    if (
      (counts.get(Role.Wolf) ?? 0) < 2 ||
      [...counts]
        .filter(
          ([role]) => role !== Role.Thief && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 2
    )
      throw new Error("thief_finite_composition_required");
    deck.push(Role.Villager, Role.Villager);
  }
  // 盗贼／千面人合法性与额外底牌已准备完毕，才比对固定底牌多重集；成功返回新数组且不洗牌。
  if (fixedRoles) {
    if (
      fixedRoles.length !== deck.length ||
      [...fixedRoles].sort().join(",") !== [...deck].sort().join(",")
    )
      throw new Error("fixed_role_deck_mismatch");
    return [...fixedRoles];
  }
  return deck;
}
